# Flood-fill hypothesis: Start from all original 3s, and recursively fill all 0s that touch them
def flood_fill_from_seeds(grid, rows, cols, seed_color, fill_color):
    """Recursively fill all cells of 0 that are connected to seed_color cells"""
    # Mark visited cells (both original seed cells and filled 0s)
    visited = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == seed_color:
                visited.add((r, c))

    # Process in BFS order
    queue = sorted(list(visited))
    filled = set()

    for r, c in queue:
        # Check 0-neighbors
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited:
                if grid[nr][nc] == 0:
                    visited.add((nr, nc))
                    filled.add((nr, nc))
                    queue.append((nr, nc))

    # Return grid with filled cells
    result = [row[:] for row in grid]
    for r, c in filled:
        result[r][c] = fill_color
    return result

